{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Case Room Backend",
    "widgets_json": {
      "case_aging": {
        "name": "Case Aging",
        "description": "Open surveillance cases by age bucket.",
        "endpoint": "/case-aging",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "data": {
          "columnsDefs": [
            {
              "field": "age_days",
              "headerName": "Age (Days)",
              "cellDataType": "number",
              "formatterFn": "int"
            },
            {
              "field": "case_id",
              "headerName": "Case ID",
              "cellDataType": "text"
            },
            {
              "field": "desk",
              "headerName": "Desk",
              "cellDataType": "text"
            }
          ]
        },
        "staleTime": 900000
      },
      "alert_queue": {
        "name": "Alert Queue",
        "description": "Open surveillance alerts.",
        "endpoint": "/alert-queue",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "severity",
            "type": "text",
            "label": "Severity",
            "value": "high",
            "options": [
              {"label": "High", "value": "high"},
              {"label": "Medium", "value": "medium"},
              {"label": "Low", "value": "low"}
            ]
          }
        ],
        "data": {
          "columnsDefs": [
            {
              "field": "alert_id",
              "headerName": "Alert",
              "cellDataType": "text"
            },
            {
              "field": "desk",
              "headerName": "Desk",
              "cellDataType": "text"
            },
            {
              "field": "severity",
              "headerName": "Severity",
              "cellDataType": "text",
              "renderFn": "titleCase"
            },
            {
              "field": "age_days",
              "headerName": "Age (d)",
              "cellDataType": "number",
              "formatterFn": "int"
            }
          ]
        },
        "staleTime": 900000
      },
      "alert_metric": {
        "name": "Open Alerts",
        "description": "Open alert count.",
        "endpoint": "/alert-count",
        "type": "metric",
        "gridData": {
          "w": 5,
          "h": 4
        }
      }
    },
    "apps_json": [
      {
        "name": "Case Room",
        "description": "Cases, alerts, posture.",
        "tabs": {
          "cases": {
            "id": "cases",
            "name": "Cases",
            "layout": [
              {
                "i": "case_aging",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              },
              {
                "i": "alert_metric",
                "x": 20,
                "y": 0,
                "w": 12,
                "h": 6
              }
            ]
          },
          "queue": {
            "id": "queue",
            "name": "Queue",
            "layout": [
              {
                "i": "alert_queue",
                "x": 0,
                "y": 0,
                "w": 24,
                "h": 10
              }
            ]
          }
        }
      }
    ]
  }
}

